"use strict";(self.webpackChunkdocs_scadys_io=self.webpackChunkdocs_scadys_io||[]).push([["1547"],{6974(e){e.exports=JSON.parse('{"version":{"pluginId":"design","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"designSidebar":[{"type":"link","href":"/design/","label":"Overview","docId":"index","unlisted":false},{"type":"category","label":"Foundations","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/design/foundations/legibility","label":"Legibility","docId":"foundations/legibility","unlisted":false},{"type":"link","href":"/design/foundations/colour","label":"Colour","docId":"foundations/colour","unlisted":false},{"type":"link","href":"/design/foundations/typography","label":"Typography","docId":"foundations/typography","unlisted":false},{"type":"link","href":"/design/foundations/layout","label":"Layout","docId":"foundations/layout","unlisted":false},{"type":"link","href":"/design/foundations/materials-and-depth","label":"Materials and depth","docId":"foundations/materials-and-depth","unlisted":false},{"type":"link","href":"/design/foundations/motion","label":"Motion","docId":"foundations/motion","unlisted":false},{"type":"link","href":"/design/foundations/night","label":"Night","docId":"foundations/night","unlisted":false},{"type":"link","href":"/design/foundations/touch-accessibility","label":"Touch accessibility","docId":"foundations/touch-accessibility","unlisted":false}],"href":"/design/foundations/"},{"type":"category","label":"Patterns","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/design/patterns/data-states","label":"Data states","docId":"patterns/data-states","unlisted":false},{"type":"link","href":"/design/patterns/alerts","label":"Alerts","docId":"patterns/alerts","unlisted":false},{"type":"link","href":"/design/patterns/gestures","label":"Gestures","docId":"patterns/gestures","unlisted":false},{"type":"link","href":"/design/patterns/page-navigation","label":"Page navigation","docId":"patterns/page-navigation","unlisted":false},{"type":"link","href":"/design/patterns/settings-and-confirmation","label":"Settings and confirmation","docId":"patterns/settings-and-confirmation","unlisted":false},{"type":"link","href":"/design/patterns/lock-and-wake","label":"Lock and wake","docId":"patterns/lock-and-wake","unlisted":false}],"href":"/design/patterns/"},{"type":"category","label":"Components","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/design/components/dials-and-rings","label":"Dials and rings","docId":"components/dials-and-rings","unlisted":false},{"type":"link","href":"/design/components/needles-and-pointers","label":"Needles and pointers","docId":"components/needles-and-pointers","unlisted":false},{"type":"link","href":"/design/components/readouts-and-windows","label":"Readouts and windows","docId":"components/readouts-and-windows","unlisted":false},{"type":"link","href":"/design/components/labels-units-and-buttons","label":"Labels, units and buttons","docId":"components/labels-units-and-buttons","unlisted":false},{"type":"link","href":"/design/components/badges-and-markers","label":"Badges and markers","docId":"components/badges-and-markers","unlisted":false},{"type":"link","href":"/design/components/vessel-outline","label":"Vessel outline","docId":"components/vessel-outline","unlisted":false}],"href":"/design/components/"}]},"docs":{"components/badges-and-markers":{"id":"components/badges-and-markers","title":"Badges and markers","description":"Badges and markers are the small flat symbols on a page. They are the SCADYS mark, the alert badge and the steer arrows. Each is exported as an alpha mask and tinted by its role, and each sits in a fixed place so the reader knows where to look for it.","sidebar":"designSidebar"},"components/dials-and-rings":{"id":"components/dials-and-rings","title":"Dials and rings","description":"A dial page is built on one shared background: a round card recessed into a flat surround, with a ring of ticks around the card\'s edge. The wind page uses a fixed ring with port and starboard sectors, and the compass page uses a card that turns with the heading.","sidebar":"designSidebar"},"components/index":{"id":"components/index","title":"Components","description":"The Components are the parts every MDD page is built from. Each page describes what the part is for, how it is drawn, what colour and type roles it takes, and which parts the firmware draws in code and which come from artwork.","sidebar":"designSidebar"},"components/labels-units-and-buttons":{"id":"components/labels-units-and-buttons","title":"Labels, units and buttons","description":"On an MDD page the labels and units are the controls. A tap on a unit changes it and a tap on a label changes what it labels, so most settings are made where their effect is seen. Buttons are kept for actions and for dialogs.","sidebar":"designSidebar"},"components/needles-and-pointers":{"id":"components/needles-and-pointers","title":"Needles and pointers","description":"Needles and pointers show an angle against a dial. Each one is drawn once, pointing straight up, and the firmware turns it about the dial centre. Each carries a letter so it is never identified by colour alone.","sidebar":"designSidebar"},"components/readouts-and-windows":{"id":"components/readouts-and-windows","title":"Readouts and windows","description":"A readout is the number a page exists to show. On a dial page it floats in a frameless window in front of the needle, and on a data page it sits centred in its cell.","sidebar":"designSidebar"},"components/vessel-outline":{"id":"components/vessel-outline","title":"Vessel outline","description":"The vessel outline puts the boat at the centre of a dial, so every angle on the dial reads relative to the bow. It is a thin line in the vessel role, drawn behind everything that carries data.","sidebar":"designSidebar"},"foundations/colour":{"id":"foundations/colour","title":"Colour","description":"Every colour on an MDD page is a named role, such as data, label or port, with one value for day and one for night. Pages, artwork and firmware refer to the role and never to a raw colour, so the whole display changes between day and night by changing the role values alone.","sidebar":"designSidebar"},"foundations/index":{"id":"foundations/index","title":"Foundations","description":"The Foundations are the rules every page follows before it shows any particular data. They set how a page is read, how it is coloured and lit, where things may sit and how it answers a touch.","sidebar":"designSidebar"},"foundations/layout":{"id":"foundations/layout","title":"Layout","description":"Every MDD page is designed once, on a square canvas of 720 \xd7 720 pixels, and each product shows that design on its own panel. Most data pages are built from two standard layouts, while the dial pages have their own.","sidebar":"designSidebar"},"foundations/legibility":{"id":"foundations/legibility","title":"Legibility","description":"An MDD display is an instrument, not a chart plotter. It shows the same page for days, usually with nobody touching it, and it is read in a glance from a helm or a bunk. Every other rule in these guidelines serves that glance.","sidebar":"designSidebar"},"foundations/materials-and-depth":{"id":"foundations/materials-and-depth","title":"Materials and depth","description":"The MIPI panels show 24-bit colour with transparency and smooth edges, so an MDD page can look built rather than printed. A dial sits recessed in its panel, a needle floats over the card and a readout window floats over the needle. Depth is used where it helps the eye find the data, and it gives way wherever it competes with the data.","sidebar":"designSidebar"},"foundations/motion":{"id":"foundations/motion","title":"Motion","description":"Movement on an MDD page carries meaning. A needle moves because the wind moved, and an alert throbs because something needs attention. Anything else that moves is noise, so a page keeps still everything that has no reason to move.","sidebar":"designSidebar"},"foundations/night":{"id":"foundations/night","title":"Night","description":"At night the display must be readable without spoiling the dark adaptation of the person reading it, or of anyone else on deck. The night palette is amber data on black, the brightness comes from the backlight rather than from the colours, and nothing on a night page is white.","sidebar":"designSidebar"},"foundations/touch-accessibility":{"id":"foundations/touch-accessibility","title":"Touch accessibility","description":"The MDD displays have no physical button, and they are used on a moving boat by people wearing sailing gloves, with spray on the glass. Every touch on the display is designed for the least precise finger in the worst conditions, and the full gesture vocabulary builds on these rules in the Patterns section.","sidebar":"designSidebar"},"foundations/typography":{"id":"foundations/typography","title":"Typography","description":"Two open-licence typefaces carry every MDD page. Noto Sans Black sets the large data values, and B612 Bold sets the dial numbers, labels and units. Every piece of text takes a named type role, which fixes its size and its typeface.","sidebar":"designSidebar"},"index":{"id":"index","title":"Display Design Guidelines","description":"These guidelines are the reference that every page, control and graphic asset on the SCADYS Marine Data Displays is designed against. They follow the shape of Apple\'s Human Interface Guidelines, cut down to a marine instrument that is read at a glance from across a cockpit by day and at night, and that is operated by a gloved, wet hand.","sidebar":"designSidebar"},"patterns/alerts":{"id":"patterns/alerts","title":"Alerts","description":"An alert is the one element on an MDD page allowed to break the quiet. It is yellow, it moves and it may outshine the data, because it is rare and has to be seen. Once it has been seen it can be snoozed, so it stops asking for attention but stays in view until it is cleared.","sidebar":"designSidebar"},"patterns/data-states":{"id":"patterns/data-states","title":"Data states","description":"Every value on an MDD page is in one of four states: valid, no data, stale or in alert. Each page shows the states the same way, so a reader who has learned one page can trust every other page.","sidebar":"designSidebar"},"patterns/gestures":{"id":"patterns/gestures","title":"Gestures","description":"The MDD displays have no physical button, so the glass provides wake, lock, home, back and escape. A small set of system gestures from the screen edges does the work of those buttons, following the iPhone, and a smaller set of page gestures acts on the page itself. Each gesture means the same thing on every page.","sidebar":"designSidebar"},"patterns/index":{"id":"patterns/index","title":"Patterns","description":"The Patterns describe how a page behaves over time and under a finger. They cover what a value shows when its data fails, how an alert asks for attention, which gesture does what, and how a setting is changed and confirmed without a keyboard.","sidebar":"designSidebar"},"patterns/lock-and-wake":{"id":"patterns/lock-and-wake","title":"Lock and wake","description":"An MDD display runs whenever it has power and spends most of its life locked. Locked, it shows its data and ignores every touch except the unlock swipe, so spray, a sleeve or a sheet of water cannot change anything.","sidebar":"designSidebar"},"patterns/page-navigation":{"id":"patterns/page-navigation","title":"Page navigation","description":"An MDD display usually shows one page for days, so navigation is occasional. When it happens it must be quick to do by feel, impossible to get lost in and always reversible with one gesture.","sidebar":"designSidebar"},"patterns/settings-and-confirmation":{"id":"patterns/settings-and-confirmation","title":"Settings and confirmation","description":"The MDD displays have no keyboard, and text and number keypads are avoided at all costs. A setting is changed with the largest, simplest control that can do the job, and an action that cannot be undone asks for a deliberate gesture before it happens.","sidebar":"designSidebar"}}}}')}}]);